import requests
from bs4 import BeautifulSoup

url = 'https://fantasy.premierleague.com/statistics'
response = requests.get(url)
soup = BeautifulSoup(response.content, 'html.parser')
stats = soup.find_all('div', class_='stat-value')

xG, xA, xGI, xGC = 0, 0, 0, 0
for stat in stats:
    if 'xG' in stat.text: xG = float(stat.text.replace(',', ''))
    elif 'xA' in stat.text: xA = float(stat.text.replace(',', ''))
    elif 'xGI' in stat.text: xGI = float(stat.text.replace(',', ''))
    elif 'xGC' in stat.text: xGC = float(stat.text.replace(',', ''))

print(f"xG: {xG}, xA: {xA}, xGI: {xGI}, xGC: {xGC}")
